import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"プライバシーポリシー","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/privacy.md","filePath":"ja/guide/privacy.md","lastUpdated":1793173149000}`),a={name:`ja/guide/privacy.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="プライバシーポリシー" tabindex="-1">プライバシーポリシー <a class="header-anchor" href="#プライバシーポリシー" aria-label="Permalink to “プライバシーポリシー”">​</a></h1><p>Sudoku は、任意のクラウド機能を備えたオフラインファーストのアプリケーションです。本ページでは、本アプリが収集するデータ（収集する場合）とその利用方法について説明します。</p><h2 id="オフラインの中核機能-—-ゲームプレイにおけるデータ収集はありません" tabindex="-1">オフラインの中核機能 — ゲームプレイにおけるデータ収集はありません <a class="header-anchor" href="#オフラインの中核機能-—-ゲームプレイにおけるデータ収集はありません" aria-label="Permalink to “オフラインの中核機能 — ゲームプレイにおけるデータ収集はありません”">​</a></h2><ul><li>パズルゲームの中核部分は完全にオフラインでプレイできます。プレイにネットワークアクセスは不要です。</li><li>設定、ゲームの状態、鉛筆メモ、統計などのすべてのゲームデータは、お使いのデバイス内にローカル保存されます。</li><li>広告、分析、サードパーティのトラッキング SDK は一切ありません。</li></ul><h2 id="任意のクラウド機能" tabindex="-1">任意のクラウド機能 <a class="header-anchor" href="#任意のクラウド機能" aria-label="Permalink to “任意のクラウド機能”">​</a></h2><h3 id="icloud-同期-cloudkit" tabindex="-1">iCloud 同期（CloudKit） <a class="header-anchor" href="#icloud-同期-cloudkit" aria-label="Permalink to “iCloud 同期（CloudKit）”">​</a></h3><p>iCloud にサインインし、同期を有効にした場合：</p><ul><li>ゲームのセーブデータ、統計、設定、デイリーチャレンジの進捗は、Apple の CloudKit サービスを通じて<strong>お客様個人の iCloud アカウント</strong>に同期されます。</li><li>データは Apple のインフラストラクチャにより、転送時および保存時のいずれにおいても暗号化されます。</li><li>同期されたデータにアクセスできるのは、お客様の Apple ID を使用するお客様ご自身のみです。</li><li>この機能は完全に任意です — 利用しなくてもアプリは問題なく動作します。</li></ul><h3 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h3><p>Game Center にサインインした場合：</p><ul><li>リーダーボードのスコア（難易度ごとのベストクリアタイム）が公開リーダーボードで共有される場合があります。</li><li>実績の進捗は Apple の Game Center サービスによって記録されます。</li><li>Game Center の表示名は、リーダーボード上で他のプレイヤーから見ることができます。</li><li>この機能は完全に任意です。</li></ul><h2 id="その他にネットワークへアクセスする唯一の機能-「more-apps」" tabindex="-1">その他にネットワークへアクセスする唯一の機能：「More Apps」 <a class="header-anchor" href="#その他にネットワークへアクセスする唯一の機能-「more-apps」" aria-label="Permalink to “その他にネットワークへアクセスする唯一の機能：「More Apps」”">​</a></h2><p>クラウド以外でネットワークにアクセスする唯一の機能は、設定内の任意の <strong>「More Apps」</strong> セクションであり、当社のサーバーから姉妹アプリの一覧を取得します。この機能は：</p><ul><li>設定 → More Apps に移動したときにのみ動作します。</li><li>アプリ名とリンクの軽量な一覧を取得するだけで、個人データの送信や保存は行いません。</li><li>まったく利用しなくてもよく、ゲームプレイには一切影響しません。</li></ul><h2 id="収集しない情報" tabindex="-1">収集しない情報 <a class="header-anchor" href="#収集しない情報" aria-label="Permalink to “収集しない情報”">​</a></h2><ul><li>個人情報、ファイル、画像、閲覧履歴は収集しません。</li><li>ゲームデータを外部サーバーに送信することはありません（上記の iCloud／Game Center に関する記載を除きます）。</li><li>サードパーティの分析 SDK や広告 SDK は組み込んでいません。</li><li>クラッシュレポートやテレメトリのサービスは使用していません。</li></ul><h2 id="権限" tabindex="-1">権限 <a class="header-anchor" href="#権限" aria-label="Permalink to “権限”">​</a></h2><p>Sudoku が必要とする権限は最小限です：</p><ul><li><strong>iCloud</strong>（任意）：CloudKit を通じてデバイス間でゲームデータを同期するため。</li><li><strong>Game Center</strong>（任意）：リーダーボードと実績のため。</li><li><strong>ネットワーク</strong>（任意）：iCloud 同期、Game Center、「More Apps」のため。</li></ul><p>位置情報、連絡先、カメラ、マイク、その他プライバシーに関わる権限は要求しません。</p><h2 id="データの保持" tabindex="-1">データの保持 <a class="header-anchor" href="#データの保持" aria-label="Permalink to “データの保持”">​</a></h2><ul><li>ローカルデータは、アプリをアンインストールするかリセットするまで、お使いのデバイス内に残ります。</li><li>iCloud で同期されたデータは、Apple の iCloud データ保持ポリシーに従います。</li><li>Game Center のデータは、Apple の Game Center ポリシーに従います。</li></ul><h2 id="プライバシーに関するご請求" tabindex="-1">プライバシーに関するご請求 <a class="header-anchor" href="#プライバシーに関するご請求" aria-label="Permalink to “プライバシーに関するご請求”">​</a></h2><p>Sudoku はすべてのデータをローカル（および任意でお客様個人の iCloud）に保存するため、当社が管理またはアクセスするサーバー側のデータは存在しません。アプリのデータをすべて消去するには：</p><ul><li>お使いのデバイスから<strong>アプリをアンインストール</strong>します。</li><li><strong>iCloud のデータをリセット</strong>：設定 → [あなたの名前] → iCloud → アカウントのストレージを管理 → Sudoku → データを削除。</li><li><strong>Mac のローカルリセット</strong>：コンテナの削除手順についてはトラブルシューティングガイドをご覧ください。</li></ul><h2 id="お子様のプライバシー" tabindex="-1">お子様のプライバシー <a class="header-anchor" href="#お子様のプライバシー" aria-label="Permalink to “お子様のプライバシー”">​</a></h2><p>Sudoku は、お子様を含む誰からも個人情報を積極的に収集することはありません。本アプリはアカウント、チャット機能、ソーシャルネットワーキングを必要としません。</p><h2 id="お問い合わせ" tabindex="-1">お問い合わせ <a class="header-anchor" href="#お問い合わせ" aria-label="Permalink to “お問い合わせ”">​</a></h2><p>プライバシーに関するご質問は、プロジェクトリポジトリ（<a href="https://github.com/sudoku-pro/sudoku-site%EF%BC%89%E3%81%A7" target="_blank" rel="noreferrer">https://github.com/sudoku-pro/sudoku-site）で</a> issue を作成するか、sudoku@w3cub.com までご連絡ください。</p>`,29)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};